#pragma once

/* Per-target menu capabilities, fixed at build time.
 *
 * A target that cannot run every shell action names a generated capability header with
 * -DGTAV_MENU_CAPABILITIES_HEADER="gtavmenu/capabilities_<target>_generated.h". That header
 * defines GTAV_CAPABILITY_ACTION_COUNT, GTAV_CAPABILITY_BITMAP_SIZE and gtav_capability_bitmap,
 * one bit per GTAV_NATIVE_SHELL_ACTION_* (generated by devtools/generators). The shared menu then
 * shows unsupported rows LOCKed with "(not supported on this target)".
 *
 * Targets without a capability header support every action, and the lock code compiles away.
 * This is a header-only check, so no target needs to provide (or weakly import) a symbol. */

#include <stdint.h>

#include "gtavmenu/native_bridge.h"

#ifdef GTAV_MENU_CAPABILITIES_HEADER
#include GTAV_MENU_CAPABILITIES_HEADER
#define GTAV_MENU_TARGET_CAPABILITIES 1
#ifdef __cplusplus
static_assert(GTAV_CAPABILITY_ACTION_COUNT == GTAV_NATIVE_SHELL_ACTION_COUNT,
              "capability header was generated for a different action list");
#else
_Static_assert(GTAV_CAPABILITY_ACTION_COUNT == GTAV_NATIVE_SHELL_ACTION_COUNT,
               "capability header was generated for a different action list");
#endif
static inline int gtav_target_action_supported(uint32_t action) {
  if (action >= GTAV_CAPABILITY_ACTION_COUNT) return 0;
  return (gtav_capability_bitmap[action >> 3] & (1u << (action & 7u))) != 0;
}
#else
#define GTAV_MENU_TARGET_CAPABILITIES 0
static inline int gtav_target_action_supported(uint32_t action) {
  (void)action;
  return 1;
}
#endif
